/**
 * Generates packages/core/src/trust-anchors.ts from the vendored CA certificates in spec/ca/, so
 * the runtime-neutral core can embed them without file-system access. Re-run after updating
 * spec/ca (and docs/sources/sources.json); packages/core/test/trust-anchors.test.ts fails while
 * the generated file is stale. Run: bun scripts/gen-trust-anchors.ts
 */
import { repoPath } from "./lib/sources.ts";

const ANCHORS = [
  [
    "eetPlaygroundRoot",
    "spec/ca/ca_eet-root_cert-playground.crt",
    "CA EET playground root (PG §3.1.2)",
  ],
  [
    "eetPlaygroundSub",
    "spec/ca/ca_eet-sub_cert-playground.crt",
    "CA EET playground issuer of cash-register certificates (PG §3.1.3)",
  ],
  ["eetProductionRoot", "spec/ca/ca_eet-root_prod.pem", "CA EET production root (P §3.1.1)"],
  [
    "eetProductionSub",
    "spec/ca/ca_eet-sub_prod.pem",
    "CA EET production issuer of cash-register certificates (P §3.1.1)",
  ],
  [
    "icaPublicCa2022",
    "spec/ca/ica/pca22_rsa.cer",
    "I.CA Public CA/RSA 06/2022, issuer of the EET response-signing certificate (PG/P §3.3)",
  ],
] as const;

function toDer(bytes: Uint8Array): Uint8Array {
  const text = new TextDecoder().decode(bytes);
  const pem = text.match(/-----BEGIN CERTIFICATE-----([\s\S]+?)-----END CERTIFICATE-----/);
  return pem?.[1] === undefined ? bytes : Buffer.from(pem[1].replace(/\s+/g, ""), "base64");
}

const lines = [
  "// Generated by scripts/gen-trust-anchors.ts from spec/ca/ — do not edit by hand.",
  "// DER certificates, base64-encoded. Provenance and SHA-256: docs/sources/sources.json.",
  "",
  "export const TRUST_ANCHORS = {",
];
for (const [name, path, comment] of ANCHORS) {
  const der = toDer(new Uint8Array(await Bun.file(repoPath(path)).arrayBuffer()));
  lines.push(`  /** ${comment} */`, `  ${name}:`, `    "${Buffer.from(der).toString("base64")}",`);
}
lines.push("} as const;", "", "export type TrustAnchorName = keyof typeof TRUST_ANCHORS;", "");

const out = repoPath("packages/core/src/trust-anchors.ts");
await Bun.write(out, lines.join("\n"));
console.log(`wrote ${out}`);
